WITH base AS (SELECT id, name, country, segment, signup_date, is_active, age, GREATEST(credit_limit, age) AS greatest_credit_limit_age FROM customers WHERE signup_date >= DATE '2023-08-26' AND city IS NOT NULL) SELECT CASE WHEN age >= 73 THEN 'LARGE' ELSE 'SMALL' END AS age_tier, PERCENTILE_APPROX(greatest_credit_limit_age, 0.95) AS greatest_credit_limit_age_p95, SIZE(COLLECT_SET(country)) AS num_countries, PERCENTILE_APPROX(greatest_credit_limit_age, 0.9) AS greatest_credit_limit_age_p90 FROM base GROUP BY 1 ORDER BY greatest_credit_limit_age_p90 NULLS LAST
